function setPath(target: Record<string, any>, path: string, value: string) {
  const parts = path.split('.')
  let current = target
  parts.slice(0, -1).forEach((part) => {
    if (!current[part]) current[part] = {}
    current = current[part] as Record<string, any>
  })
  current[parts.at(-1)!] = value
}

export function buildMessages() {
  return Object.fromEntries(UI_LOCALES.map((locale, localeIndex) => {
    const nested: Record<string, any> = {}
    Object.entries(copy).forEach(([key, values]) => setPath(nested, key, values[localeIndex]))
    return [locale, nested]
  }))
}

export type CopyKey = keyof typeof copy

export function copyText(key: CopyKey, locale: string) {
  const index = Math.max(0, UI_LOCALES.indexOf(locale as (typeof UI_LOCALES)[number]))
  return copy[key][index]
}
